      es: ["La longitud del muelle es de aproximadamente 6,5 kilómetros.", "La terminal moderna fue inaugurada en 1989.", "Manejo de más de 100.000 TEU de carga de contenedores al año.", "Crucial para la importación de combustibles y cereales a Yucatán.", "Se encuentra a 36 kilómetros de la ciudad de Mérida.", "Designada como Zona Económica Estratégica (ZEE)."],
      pt: ["O comprimento do píer é de cerca de 6,5 quilómetros.", "O terminal moderno foi inaugurado em 1989.", "Movimentação de mais de 100.000 TEU de carga de contentores anualmente.", "Crucial para a importação de combustíveis e cereais para Yucatán.", "Localizado a 36 quilómetros da cidade de Mérida.", "Designado como Zona Económica Estratégica (EEZ)."],
