      de: ["Standort bei Monterrey", "Produziert schwefelarmes Benzin", "Strategisch für den Norden", "Hoher Grad an Automatisierung"],
      hu: ["Monterrey közelében található", "Alacsony kéntartalmú benzint gyárt", "Stratégiai fontosságú északon", "Magas fokú automatizálás"],
