      ro: "Unul dintre cele mai mari complexe de procesare a gazelor naturale din Chiapas, esențial pentru aprovizionarea cu energie din sud.",
      en: "One of the largest natural gas processing complexes in Chiapas, crucial for the energy supply of southern Mexico.",
