      es: ["Procesa gas asociado", "Produce gas líquido y azufre", "Estratégico para PEMEX", "Ubicado en el estado de Chiapas"],
      pt: ["Processa gás associado", "Produz gás líquido e enxofre", "Estratégico para a PEMEX", "Localizado no estado de Chiapas"],
