      es: ["Base para la construcción del Tren Maya", "Acceso a aguas profundas", "Centro de transbordo de cemento", "Importante para las canteras locales"],
      pt: ["Base para a construção do Trem Maia", "Acesso a águas profundas", "Local de transbordo de cimento", "Importante para pedreiras locais"],
