      hu: ["Seybaplaya körülbelül 30 kilométerre délnyugatra fekszik Campeche városától.", "A kikötő modern terminállal rendelkezik az ömlesztett áruk átrakodásához.", "Fontos logisztikai pont a Tren Maya projekt építéséhez.", "A rakpartokat megerősítették a nagyobb merülésű hajók számára.", "A kikötő támogatja a Pemex tevékenységét a Campeche-öbölben.", "2019-ben avatták fel a kikötő első luxushajó-terminálját."],
      ro: ["Seybaplaya este situat la aproximativ 30 de kilometri sud-vest de orașul Campeche.", "Portul dispune de un terminal modern pentru manipularea mărfurilor în vrac.", "Este un punct logistic important pentru construcția proiectului Tren Maya.", "Moloale au fost consolidate pentru a primi nave cu pescaj mai mare.", "Portul susține activitățile Pemex în regiunea marină a Campeche.", "În anul 2019, a fost inaugurat primul terminal de croazieră din port."],
      en: ["Seybaplaya is located about 30 kilometers southwest of the city of Campeche.", "The port features a modern terminal for the handling of bulk cargo.", "It serves as a key logistics point for the construction of the Tren Maya project.", "The quays have been reinforced to accommodate vessels with deeper drafts.", "The port supports Pemex operations in the Campeche Sound region.", "The first cruise ship terminal in the port was inaugurated in 2019."],
      es: ["Seybaplaya se encuentra a unos 30 kilómetros al suroeste de la ciudad de Campeche.", "El puerto cuenta con una terminal moderna para el manejo de carga a granel.", "Es un punto logístico importante para la construcción del proyecto Tren Maya.", "Los muros del muelle fueron reforzados para barcos con mayor calado.", "El puerto apoya las actividades de Pemex en la región de la Sonda de Campeche.", "En 2019 se inauguró la primera terminal de cruceros en el puerto."],
      pt: ["Seybaplaya localiza-se a cerca de 30 quilómetros a sudoeste da cidade de Campeche.", "O porto possui um terminal moderno para a movimentação de granéis.", "É um ponto logístico importante para a construção do projeto Tren Maya.", "As paredes do cais foram reforçadas para navios com maior calado.", "O porto apoia as atividades da Pemex na região da Sonda de Campeche.", "Em 2019, foi inaugurado o primeiro terminal de cruzeiros no porto."],
      fr: ["Seybaplaya se situe à environ 30 kilomètres au sud-ouest de la ville de Campeche.", "Le port dispose d'un terminal moderne pour le traitement du fret en vrac.", "C'est un point logistique important pour la construction du projet Tren Maya.", "Les quais ont été renforcés pour accueillir des navires à plus fort tirant d'eau.", "Le port soutient les activités de Pemex dans la région de la Sonde de Campeche.", "En 2019, le premier terminal de croisière a été inauguré dans le port."],
